SELECT 
    (SELECT COUNT("hex_id_l7") FROM "hex_county_state_zip_crosswalk" WHERE "County" = 'Cameron' AND "hex_id_l7" IN (SELECT "hex_id" FROM "VUL_002" WHERE "sovi" IS NOT NULL)) / 
    (SELECT COUNT("hex_id_l7") FROM "hex_county_state_zip_crosswalk" WHERE "County" = 'Cameron') AS coverage_fraction;

