FROM "HIFLD-EMERGENC-FIRE_EMS-N"
WHERE "hex_id" IN (
  SELECT "hex_id" FROM "VUL_002" WHERE "sovi" > 0.5
) AND "hex_id" IN (
  SELECT "hex_id" FROM "CRIT_LIFE_003" WHERE "conc_index_hospital" > 0.5
);

